58	/**
59	 * Security configuration.
60	 *
61	 * For historical reasons, most of the actual configuration values are stored in {@link Jenkins}.
62	 *
63	 * @author Kohsuke Kawaguchi
64	 */
65	@Extension(ordinal = Integer.MAX_VALUE - 210) @Symbol("securityConfig")
66	public class GlobalSecurityConfiguration extends ManagementLink implements Describable<GlobalSecurityConfiguration> {
67	
68	    private static final Logger LOGGER = Logger.getLogger(GlobalSecurityConfiguration.class.getName());
69	
70	    public SecurityRealm getSecurityRealm() {
71	        return Jenkins.get().getSecurityRealm();
72	    }
73	
74	    public AuthorizationStrategy getAuthorizationStrategy() {
75	        return Jenkins.get().getAuthorizationStrategy();
76	    }
77	
78	    public MarkupFormatter getMarkupFormatter() {
79	        return Jenkins.get().getMarkupFormatter();
80	    }
81	
82	    public int getSlaveAgentPort() {
83	        return Jenkins.get().getSlaveAgentPort();
84	    }
85	
86	    /**
87	     * @since 2.24
88	     * @return true if the inbound agent port is enforced on this instance.
89	     */
90	    @Restricted(NoExternalUse.class)
91	    public boolean isSlaveAgentPortEnforced() {
92	        return Jenkins.get().isSlaveAgentPortEnforced();
93	    }
94	
95	    @NonNull
96	    public Set<String> getAgentProtocols() {
97	        return Jenkins.get().getAgentProtocols();
98	    }
99	
100	    public boolean isDisableRememberMe() {
101	        return Jenkins.get().isDisableRememberMe();
102	    }
103	
104	    @NonNull
105	    @Override
106	    public Category getCategory() {
107	        return Category.SECURITY;
108	    }
109	
110	    @POST
111	    public synchronized void doConfigure(StaplerRequest req, StaplerResponse rsp) throws IOException, ServletException, FormException {
112	        // for compatibility reasons, the actual value is stored in Jenkins
113	        JSONObject json = req.getSubmittedForm();
114	        BulkChange bc = new BulkChange(Jenkins.get());
115	        try {
116	            boolean result = configure(req, json);
117	            LOGGER.log(Level.FINE, "security saved: " + result);
118	            Jenkins.get().save();
119	            FormApply.success(req.getContextPath() + "/manage").generateResponse(req, rsp, null);
120	        } catch (JSONException x) {
121	            LOGGER.warning(() -> "Bad JSON:\n" + json.toString(2));
122	            throw x;
123	        } finally {
124	            bc.commit();
125	        }
126	    }
127	
128	    public boolean configure(StaplerRequest req, JSONObject json) throws FormException {
129	        // for compatibility reasons, the actual value is stored in Jenkins
130	        Jenkins j = Jenkins.get();
131	        j.checkPermission(Jenkins.ADMINISTER);
132	
133	        j.setDisableRememberMe(json.optBoolean("disableRememberMe", false));
134	        // TODO probably clearer to configure such things with @DataBoundSetter
135	        j.setSecurityRealm(Descriptor.bindJSON(req, SecurityRealm.class, json.getJSONObject("securityRealm")));
136	        j.setAuthorizationStrategy(Descriptor.bindJSON(req, AuthorizationStrategy.class, json.getJSONObject("authorizationStrategy")));
137	
138	        if (json.has("markupFormatter")) {
139	            j.setMarkupFormatter(req.bindJSON(MarkupFormatter.class, json.getJSONObject("markupFormatter")));
140	        } else {
141	            j.setMarkupFormatter(null);
142	        }
143	
144	        // Agent settings
145	        if (!isSlaveAgentPortEnforced()) {
146	            try {
147	                j.setSlaveAgentPort(new ServerTcpPort(json.getJSONObject("slaveAgentPort")).getPort());
148	            } catch (IOException e) {
149	                throw new FormException(e, "slaveAgentPortType");
150	            }
151	        }
152	        Set<String> agentProtocols = new TreeSet<>();
153	        if (json.has("agentProtocol")) {
154	            Object protocols = json.get("agentProtocol");
155	            if (protocols instanceof JSONArray) {
156	                for (int i = 0; i < ((JSONArray) protocols).size(); i++) {
157	                    agentProtocols.add(((JSONArray) protocols).getString(i));
158	                }
159	            } else {
160	                agentProtocols.add(protocols.toString());
161	            }
162	        }
163	        j.setAgentProtocols(agentProtocols);
164	
165	        // persist all the additional security configs
166	        boolean result = true;
167	        for (Descriptor<?> d : Functions.getSortedDescriptorsForGlobalConfigByDescriptor(FILTER)) {
168	            result &= configureDescriptor(req, json, d);
169	        }
170	
171	        return result;
172	    }
173	
174	    private boolean configureDescriptor(StaplerRequest req, JSONObject json, Descriptor<?> d) throws FormException {
175	        // collapse the structure to remain backward compatible with the JSON structure before 1.
176	        String name = d.getJsonSafeClassName();
177	        JSONObject js = json.has(name) ? json.getJSONObject(name) : new JSONObject(); // if it doesn't have the property, the method returns invalid null object.
178	        json.putAll(js);
179	        return d.configure(req, js);
180	    }
181	
182	    @Override
183	    public String getDisplayName() {
184	        return getDescriptor().getDisplayName();
185	    }
