212	     * @see Describable#getDescriptor()
213	     */
214	    @SuppressWarnings("unchecked")
215	    @Override
216	    public Descriptor<GlobalSecurityConfiguration> getDescriptor() {
217	        return Jenkins.get().getDescriptorOrDie(getClass());
218	    }
