221	    public static final class DescriptorImpl extends Descriptor<GlobalSecurityConfiguration> {
222	        @NonNull
223	        @Override
224	        public String getDisplayName() {
225	            return Messages.GlobalSecurityConfiguration_DisplayName();
226	        }
227	    }
228	}

